SysDataModelXML.SQLUpdateScript:
--LINKADDNEWROWS --LINKAUTOREPLACEEMPTYCOLUMNS DECLARE @NUM INT;
SELECT @NUM = Isnull(Max(DOCLIN), 0) + 10 FROM [MFGPKL] WHERE DOCNUM = N'#DOCNUM#';
MERGE INTO [MFGPKL] D USING (SELECT N'@DOCNUM@' DOCNUM ,Iif(0#DOCLIN# = 0, @NUM, 0#DOCLIN#) DOCLIN ,'MPH' DOCTYP ,N'#CPNITMNO#' CPNITMNO ,N'#CPNITMVER#' CPNITMVER ,N'#CPNLOT#' CPNLOT ,N'#CPNSUBLOT#' CPNSUBLOT ,0#QTY# QTY ,N'#UOM#' UOM ,01 UOMCOE ,0#QTY# QTYSTU ,N'#LREMARK#' REMARK ,N'#SRCTYP#' SRCTYP ,N'#SRCDOC#' SRCDOC ,0#SRCLIN# SRCLIN ,0#SRCSEQ# SRCSEQ ,N'#CLOREA#' CLOREA ,N'1' DOCSTA ,N'#LOGIN_USER#' CREUSR ,Getdate() CRETIM) S ON ( S.[DOCNUM] = D.[DOCNUM] AND S.DOCLIN = D.DOCLIN ) WHEN MATCHED THEN UPDATE SET CPNITMNO = S.CPNITMNO ,CPNITMVER = S.CPNITMVER ,CPNLOT = S.CPNLOT ,CPNSUBLOT = S.CPNSUBLOT ,QTY = S.QTY ,UOM = S.UOM ,UOMCOE = S.UOMCOE ,QTYSTU = S.QTYSTU ,DOCSTA = S.DOCSTA ,REMARK = S.REMARK ,SRCTYP = S.SRCTYP ,SRCDOC = S.SRCDOC ,SRCLIN = S.SRCLIN ,SRCSEQ = S.SRCSEQ ,UPDUSR = '#LOGIN_USER#' ,UPDTIM = Getdate() WHEN NOT MATCHED THEN INSERT (DOCTYP ,DOCNUM ,DOCLIN ,CPNITMNO ,CPNITMVER ,CPNLOT ,CPNSUBLOT ,QTY ,UOM ,UOMCOE ,QTYSTU ,DOCSTA ,REMARK ,SRCTYP ,SRCDOC ,SRCLIN ,SRCSEQ ,CREUSR ,CRETIM ) VALUES ( S.DOCTYP ,S.DOCNUM ,S.DOCLIN ,S.CPNITMNO ,S.CPNITMVER ,S.CPNLOT ,S.CPNSUBLOT ,S.QTY ,S.UOM ,S.UOMCOE ,S.QTYSTU ,S.DOCSTA ,S.REMARK ,S.SRCTYP ,S.SRCDOC ,S.SRCLIN ,S.SRCSEQ ,S.CREUSR ,S.CRETIM );
